import { Component, OnInit } from '@angular/core';
import { ActivatedRoute } from '@angular/router';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';

/** Public company profile page (no login required). */
@Component({
  selector: 'app-company',
  templateUrl: './company.component.html',
  styleUrls: ['./company.component.css']
})
export class CompanyComponent implements OnInit {

  companyId!: number;
  company!: Company;
  jobs: Job[] = [];

  constructor(
    private compService: CompanyService,
    private route: ActivatedRoute
  ) {}

  ngOnInit(): void {
    const routeId = this.route.snapshot.paramMap.get('id');
    this.companyId = routeId ? Number(routeId) : Number(localStorage.getItem('id'));

    this.getCompanyById();
    this.getJobsByCompany();
  }

  getCompanyById() {
    this.compService.getCompanyById(this.companyId).subscribe(res => this.company = res);
  }

  getJobsByCompany() {
    this.compService.getJobsByCompany(this.companyId).subscribe(res => this.jobs = res);
  }
}
<div class="page">
<app-header variant="guest"></app-header>

<main class="content">
<section class="section-pad">
  <div class="wrap">
    <div class="card" style="margin-bottom:28px;">
      <h1 style="font-size:24px;">{{company?.companyName}}</h1>
      <p class="muted" style="margin-top:4px;">{{company?.location}} &middot; {{company?.website}}</p>
      <p style="margin-top:12px;font-size:14px;">{{company?.description}}</p>
    </div>
    <div class="section-head"><h2>Roles at {{company?.companyName}} ({{jobs.length}})</h2></div>
    <div class="card-row-3">
      <div class="job-card" *ngFor="let job of jobs">
        <div class="top">
          <h3 style="font-size:15px;">{{job.jobTitle}}</h3>
          <span class="chip" [class.chip-open]="job.active" [class.chip-closed]="!job.active">{{ job.active ? 'Open' : 'Closed' }}</span>
        </div>
        <div class="meta">{{job.location}} &middot; &#8377;{{job.salary}}</div>
      </div>
    </div>
  </div>
</section>
</main>


<app-footer></app-footer>
</div>
